sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {

    var counts = { asset_passport: 0, service_log: 0, ownership_transfer_case: 0, fraud_report: 0, compliance_record: 0 };
    var flagged = [];

    // ══════════════════════════════════════════════════════════
    // 1. ASSET PASSPORTS (4 records)
    // ══════════════════════════════════════════════════════════
    var passports = [
        { name: 'iPhone 14 Pro - Refurb Unit A',  serial: 'SN-DEMO-1001', model: 'iPhone 14 Pro',    passport_status: 'active',    statu0: 'active',   batch: 'BATCH-2024-A' },
        { name: 'Samsung Galaxy S23 - Unit B',     serial: 'SN-DEMO-1002', model: 'Galaxy S23',       passport_status: 'active',    statu0: 'verified', batch: 'BATCH-2024-A' },
        { name: 'Google Pixel 8 - Suspended Unit', serial: 'SN-DEMO-1003', model: 'Pixel 8',          passport_status: 'suspended', statu0: 'suspended', batch: 'BATCH-2024-B' },
        { name: 'OnePlus 12 - Clean Unit',         serial: 'SN-DEMO-1004', model: 'OnePlus 12',       passport_status: 'active',    statu0: 'active',   batch: 'BATCH-2024-B' }
    ];
    var apIds = [];
    for (var i = 0; i < passports.length; i++) {
        var p = passports[i];
        var ap = new GlideRecord('x_1919710_refurt_0_asset_passport');
        ap.initialize();
        ap.setValue('name', p.name);
        ap.setValue('serial_number', p.serial);
        ap.setValue('model_number', p.model);
        ap.setValue('passport_status', p.passport_status);
        ap.setValue('statu0', p.statu0);
        ap.setValue('batch_code', p.batch);
        ap.setValue('short_description', 'Demo asset passport: ' + p.name);
        var id = ap.insert();
        apIds.push(id + '');
        counts.asset_passport++;
    }

    // ══════════════════════════════════════════════════════════
    // 2. SERVICE LOGS (3 records — 2 OTP verified, 1 not)
    // ══════════════════════════════════════════════════════════
    var serviceLogs = [
        { ap: 0, type: 'repair',      tech: 'Maria Chen',   notes: 'Screen replacement completed', otpVerify: true },
        { ap: 1, type: 'inspection',   tech: 'James Okafor', notes: 'Full diagnostic check passed', otpVerify: true },
        { ap: 3, type: 'maintenance',  tech: 'Priya Sharma', notes: 'Battery health check pending OTP', otpVerify: false }
    ];
    for (var s = 0; s < serviceLogs.length; s++) {
        var sl = serviceLogs[s];
        // Step 1: Insert — BR forces otp_verified=false, otp_code=''
        var slGr = new GlideRecord('x_1919710_refurt_0_service_log');
        slGr.initialize();
        slGr.setValue('asset_passport', apIds[sl.ap]);
        slGr.setValue('service_type', sl.type);
        slGr.setValue('technician_name', sl.tech);
        slGr.setValue('service_notes', sl.notes);
        slGr.setValue('service_date', new GlideDate().getDisplayValue());
        slGr.setValue('status', sl.otpVerify ? 'completed' : 'open');
        var slId = slGr.insert();

        if (sl.otpVerify) {
            // Step 2: Generate real OTP code
            var util = new OTPUtil();
            var code = util.generateOTP(slId + '');

            // Step 3: Update with the OTP code — attempt real workflow
            var slUpd = new GlideRecord('x_1919710_refurt_0_service_log');
            slUpd.get(slId);
            slUpd.setWorkflow(true);
            slUpd.setValue('otp_code', code);
            slUpd.update();

            // Fallback: if BR didn't fire in script context, set directly
            var check = new GlideRecord('x_1919710_refurt_0_service_log');
            check.get(slId);
            if (check.getValue('otp_verified') != '1') {
                check.setValue('otp_verified', 'true');
                check.setValue('otp_code', '');
                check.setWorkflow(false);
                check.update();
            }
        }
        counts.service_log++;
    }

    // ══════════════════════════════════════════════════════════
    // 3. FRAUD REPORTS (6 records — 3 on AP-1, 3 on AP-2)
    //    Triggers "Calculate Fraud Risk Score" BR to flag both
    // ══════════════════════════════════════════════════════════
    // AP-1: 3 reports — first confirmed, then 2 trigger scoring
    var fraudData = [
        { ap: 0, type: 'counterfeit_suspected', desc: 'Serial number inconsistency detected',       status: 'confirmed',    report: 'FR-DEMO-001' },
        { ap: 0, type: 'invalid_qr',            desc: 'QR code does not resolve to expected URL',   status: 'under_review', report: 'FR-DEMO-002' },
        { ap: 0, type: 'ownership_mismatch',     desc: 'Registered owner does not match seller ID',  status: 'investigating', report: 'FR-DEMO-003' },
        // AP-2: 3 reports — first confirmed, then 2 trigger scoring
        { ap: 1, type: 'expired_compliance',     desc: 'Compliance certificate expired 6 months ago', status: 'confirmed',    report: 'FR-DEMO-004' },
        { ap: 1, type: 'counterfeit_suspected',  desc: 'IMEI does not match manufacturer database',   status: 'under_review', report: 'FR-DEMO-005' },
        { ap: 1, type: 'other',                  desc: 'Multiple ownership transfers in 30 days',     status: 'investigating', report: 'FR-DEMO-006' }
    ];
    for (var f = 0; f < fraudData.length; f++) {
        var fd = fraudData[f];
        var fr = new GlideRecord('x_1919710_refurt_0_fraud_report');
        fr.initialize();
        fr.setValue('asset_passport', apIds[fd.ap]);
        fr.setValue('issue_type', fd.type);
        fr.setValue('description', fd.desc);
        fr.setValue('status', fd.status);
        fr.setValue('report_number', fd.report);
        fr.setValue('reported_on', new GlideDateTime().getDisplayValue());
        fr.insert();
        counts.fraud_report++;
    }

    // Check which passports got flagged
    for (var g = 0; g < 2; g++) {
        var apCheck = new GlideRecord('x_1919710_refurt_0_asset_passport');
        apCheck.get(apIds[g]);
        var ps = apCheck.getValue('passport_status');
        var rs = apCheck.getValue('risk_score');
        if (ps == 'flagged') {
            flagged.push(apIds[g] + ' (' + apCheck.getValue('name') + ') risk_score=' + rs);
        }
    }

    // ══════════════════════════════════════════════════════════
    // 4. OWNERSHIP TRANSFER CASE (1 record)
    // ══════════════════════════════════════════════════════════
    var otc = new GlideRecord('x_1919710_refurt_0_ownership_transfer_case');
    otc.initialize();
    otc.setValue('asset_passport', apIds[3]);
    otc.setValue('transfer_status', 'pending');
    otc.setValue('owner_consent_status', 'approved');
    otc.setValue('buyer_consent_status', 'pending');
    otc.setValue('transfer_request_date', new GlideDateTime().getDisplayValue());
    otc.insert();
    counts.ownership_transfer_case++;

    // ══════════════════════════════════════════════════════════
    // 5. COMPLIANCE RECORDS (1 record)
    // ══════════════════════════════════════════════════════════
    var compData = [
        { ap: 0, type: 'safety',   status: 'verified', cert: 'DEMO-CERT-001', pass: 'pass', issued: 'National Safety Board' }
    ];
    for (var c = 0; c < compData.length; c++) {
        var cd = compData[c];
        var cr = new GlideRecord('x_1919710_refurt_0_compliance_record');
        cr.initialize();
        cr.setValue('asset_passport', apIds[cd.ap]);
        cr.setValue('compliance_type', cd.type);
        cr.setValue('compliance_status', cd.status);
        cr.setValue('certificate_number', cd.cert);
        cr.setValue('pass_fail', cd.pass);
        cr.setValue('issued_by', cd.issued);
        cr.setValue('issue_date', '2024-06-15');
        cr.setValue('expiry_date', '2026-06-15');
        cr.insert();
        counts.compliance_record++;
    }

    // ══════════════════════════════════════════════════════════
    // SUMMARY
    // ══════════════════════════════════════════════════════════
    var total = counts.asset_passport + counts.service_log + counts.ownership_transfer_case + counts.fraud_report + counts.compliance_record;
    var msg = 'Created ' + total + ' records: ' +
        counts.asset_passport + ' asset_passports, ' +
        counts.service_log + ' service_logs, ' +
        counts.fraud_report + ' fraud_reports, ' +
        counts.ownership_transfer_case + ' ownership_transfer_cases, ' +
        counts.compliance_record + ' compliance_records. ' +
        'Flagged passports: ' + (flagged.length > 0 ? flagged.join(' | ') : 'NONE (BR may not have fired on insert)');

    stepResult.setOutputMessage(msg);
    outputs.summary = msg;
    outputs.flagged = flagged.join(' | ');

})(outputs, steps, params, stepResult, assertEqual);

